DO $publish$ DECLARE j jsonb := $expected$[{"language":"es","slug":"farofa-platano-maduro","public_path":"/farofa-platano-maduro","title":"Farofa de plátano maduro con harina de mandioca","excerpt":"Farofa brasileña de banana-da-terra: harina de mandioca tostada con plátano maduro, cebolla y mantequilla. Una guarnición suelta y dorada para seis porciones.","summary":"Farofa brasileña de banana-da-terra: harina de mandioca tostada con plátano maduro, cebolla y mantequilla. Una guarnición suelta y dorada para seis porciones.","notes":"<p>La farinha de mandioca tostada es harina granulada de yuca, no almidón de tapioca ni fécula para pandebono. La banana-da-terra es plátano de cocinar, no banana dulce de postre. Contiene leche por la mantequilla. Refrigera las sobras pronto y consúmelas en 2 días; recalienta suavemente en sartén sin añadir agua.</p><h2>También puedes preparar</h2><ul><li><a href=\"/receta-de-feijoada\">Feijoada casera de alubias negras y cerdo</a></li><li><a href=\"/arroz-blanco-perfecto\">Arroz blanco suelto por absorción</a></li></ul>","content_html":"<p>Farofa brasileña de banana-da-terra: harina de mandioca tostada con plátano maduro, cebolla y mantequilla. Una guarnición suelta y dorada para seis porciones.</p><p>La farinha de mandioca tostada es harina granulada de yuca, no almidón de tapioca ni fécula para pandebono. La banana-da-terra es plátano de cocinar, no banana dulce de postre. Contiene leche por la mantequilla. Refrigera las sobras pronto y consúmelas en 2 días; recalienta suavemente en sartén sin añadir agua.</p><h2>También puedes preparar</h2><ul><li><a href=\"/receta-de-feijoada\">Feijoada casera de alubias negras y cerdo</a></li><li><a href=\"/arroz-blanco-perfecto\">Arroz blanco suelto por absorción</a></li></ul>","ingredients":[{"name":"Plátano maduro, pulpa sin cáscara","amount":"300","unit":"g"},{"name":"Harina de mandioca tostada para farofa","amount":"180","unit":"g"},{"name":"Mantequilla sin sal","amount":"35","unit":"g"},{"name":"Cebolla pelada","amount":"100","unit":"g"},{"name":"Cebollino fresco","amount":"10","unit":"g"},{"name":"Sal","amount":"2","unit":"g"},{"name":"Pimienta negra molida","amount":"0.5","unit":"g"}],"steps":[{"title":"Prepara el plátano","content":"Pela los plátanos y pesa 300 g de pulpa. Corta en dados de 1,5 cm; deben estar maduros, pero firmes para no convertirse en puré.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-01.webp","image_alt":"Farofa de plátano maduro con harina de mandioca: Prepara el plátano"},{"title":"Pica los aromáticos","content":"Pica fina la cebolla y corta el cebollino. Pesa la harina y separa la mantequilla: 20 g para el plátano y 15 g para la cebolla.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-02.webp","image_alt":"Farofa de plátano maduro con harina de mandioca: Pica los aromáticos"},{"title":"Dora el plátano","content":"Funde 20 g de mantequilla en una sartén amplia. Dora el plátano a fuego medio 5–7 minutos, girando con cuidado hasta obtener bordes dorados.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-03.webp","image_alt":"Farofa de plátano maduro con harina de mandioca: Dora el plátano"},{"title":"Retira sin aplastar","content":"Pasa el plátano a un plato con una espátula, conservando los dados enteros. Deja la sartén sobre fuego medio-bajo para continuar.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-04.webp","image_alt":"Farofa de plátano maduro con harina de mandioca: Retira sin aplastar"},{"title":"Ablanda la cebolla","content":"Añade los 15 g de mantequilla restantes y la cebolla. Cocina 5–6 minutos, removiendo, hasta que esté tierna y apenas dorada. No quemes la mantequilla.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-05.webp","image_alt":"Farofa de plátano maduro con harina de mandioca: Ablanda la cebolla"},{"title":"Tuesta la harina","content":"Incorpora la harina de mandioca tostada. Remueve a fuego bajo 3–4 minutos para calentarla y repartir la grasa: debe seguir suelta, no convertirse en masa.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-06.webp","image_alt":"Farofa de plátano maduro con harina de mandioca: Tuesta la harina"},{"title":"Integra y sazona","content":"Devuelve el plátano a la sartén. Mezcla suavemente, añade sal, pimienta y cebollino, calienta 1 minuto y apaga el fuego.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-07.webp","image_alt":"Farofa de plátano maduro con harina de mandioca: Integra y sazona"},{"title":"Sirve como guarnición","content":"Reparte en seis porciones pequeñas y sirve templada. Mantén la harina suelta y los dados de plátano enteros; no añadas agua.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-08.webp","image_alt":"Farofa de plátano maduro con harina de mandioca: Sirve como guarnición"}],"category":"Guarniciones","course":"Guarniciones","cuisine":"Brasileña","difficulty":"Fácil","prep_time_minutes":10,"cook_time_minutes":20,"total_time_minutes":30,"servings":6,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada.webp","alt":"Farofa de plátano maduro con harina de mandioca"}],"video_urls":[],"keywords":["Farofa de plátano maduro con harina de mandioca","Plátano maduro, pulpa sin cáscara","Harina de mandioca tostada para farofa"],"nutrition":{"calories":216,"protein_g":1.3,"carbs_g":44.4,"fat_g":5.0,"saturated_fat_g":3.0,"fiber_g":3.2,"sodium_mg":136.0,"estimated":true,"serving_size":"1 de 6 porciones","source":"USDA FoodData Central SR Legacy + TBCA BRC0088B","source_url":"https://www.tbca.net.br/base-dados-en/int_statistical_composition.php?cod_produto=BRC0088B","method":"Suma de referencias por peso, dividida entre las porciones; todos los ingredientes principales contabilizados.","note":"Estimación orientativa, no medición del plato cocinado. Las marcas y el escurrido cambian los valores; los nutrientes sin dato completo no se muestran. Referencias genéricas para mostaza preparada, crema, boniato, aceite y chocolate; las variedades y marcas concretas pueden diferir."},"seo":{"title":"Farofa de plátano maduro con harina de mandioca","description":"Farofa brasileña de banana-da-terra: harina de mandioca tostada con plátano maduro, cebolla y mantequilla. Una guarnición suelta y dorada para seis porciones.","image_alt":"Farofa de plátano maduro con harina de mandioca","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada-16x9.webp"],"faq":[{"q":"¿Sirve la fécula de tapioca?","a":"No. No tiene la textura granulada de la farofa y puede formar grumos. Busca farinha de mandioca tostada en la etiqueta."},{"q":"¿Debe quedar como un puré?","a":"No. La harina debe quedar suelta, con los dados de plátano visibles. No añadas agua ni aplastes la fruta."},{"q":"¿Con qué se acompaña?","a":"Con arroz, frijoles, carnes asadas o verduras. Esos acompañamientos no se incluyen en las cantidades ni en la nutrición."}],"rest_time_minutes":0},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"89f06449-417d-48df-bcfe-628c059eb3ca"},{"language":"de","slug":"farofa-kochbanane-geroestetes-maniokmehl","public_path":"/de/farofa-kochbanane-geroestetes-maniokmehl","title":"Farofa mit Kochbanane und geröstetem Maniokmehl","excerpt":"Brasilianische Farofa mit reifer Kochbanane, Butter und grobem geröstetem Maniokmehl. Eine lockere, goldene Beilage für sechs in etwa 30 Minuten.","summary":"Brasilianische Farofa mit reifer Kochbanane, Butter und grobem geröstetem Maniokmehl. Eine lockere, goldene Beilage für sechs in etwa 30 Minuten.","notes":"<p>Grobes geröstetes Maniokmehl (farinha de mandioca torrada) verwenden, keine Tapiokastärke. Kochbanane statt weicher Dessertbanane nehmen. Enthält Milch durch Butter. Reste innerhalb von 2 Stunden kühlen und in 2 Tagen verbrauchen; in einer trockenen Pfanne aufwärmen. Die Maniokreferenz stammt aus der brasilianischen TBCA; Gesamtzucker fehlt mangels vollständiger Daten.</p><h2>Auch ausprobieren</h2><ul><li><a href=\"/de/feijoada-rezept\">Feijoada mit schwarzen Bohnen und Schweinefleisch</a></li><li><a href=\"/de/lockerer-weisser-reis\">Lockerer weißer Reis nach der Quellmethode</a></li></ul>","content_html":"<p>Brasilianische Farofa mit reifer Kochbanane, Butter und grobem geröstetem Maniokmehl. Eine lockere, goldene Beilage für sechs in etwa 30 Minuten.</p><p>Grobes geröstetes Maniokmehl (farinha de mandioca torrada) verwenden, keine Tapiokastärke. Kochbanane statt weicher Dessertbanane nehmen. Enthält Milch durch Butter. Reste innerhalb von 2 Stunden kühlen und in 2 Tagen verbrauchen; in einer trockenen Pfanne aufwärmen. Die Maniokreferenz stammt aus der brasilianischen TBCA; Gesamtzucker fehlt mangels vollständiger Daten.</p><h2>Auch ausprobieren</h2><ul><li><a href=\"/de/feijoada-rezept\">Feijoada mit schwarzen Bohnen und Schweinefleisch</a></li><li><a href=\"/de/lockerer-weisser-reis\">Lockerer weißer Reis nach der Quellmethode</a></li></ul>","ingredients":[{"name":"Reife Kochbanane, geschält","amount":"300","unit":"g"},{"name":"Grobes geröstetes Maniokmehl","amount":"180","unit":"g"},{"name":"Ungesalzene Butter","amount":"35","unit":"g"},{"name":"Geschälte Zwiebel","amount":"100","unit":"g"},{"name":"Frischer Schnittlauch","amount":"10","unit":"g"},{"name":"Salz","amount":"2","unit":"g"},{"name":"Gemahlener schwarzer Pfeffer","amount":"0.5","unit":"g"}],"steps":[{"title":"Kochbanane schneiden","content":"Reife Kochbanane schälen und 300 g Fruchtfleisch abwiegen. In 1,5 cm große Würfel schneiden; reife, aber noch feste Früchte wählen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-01.webp","image_alt":"Farofa mit Kochbanane und geröstetem Maniokmehl: Kochbanane schneiden"},{"title":"Zutaten bereitstellen","content":"Zwiebel und Schnittlauch fein schneiden. 180 g geröstetes Maniokmehl abwiegen und Butter in 20 g und 15 g aufteilen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-02.webp","image_alt":"Farofa mit Kochbanane und geröstetem Maniokmehl: Zutaten bereitstellen"},{"title":"Kochbanane bräunen","content":"20 g Butter in einer großen Pfanne bei mittlerer Hitze schmelzen. Kochbanane 5–7 Minuten vorsichtig wenden und auf mehreren Seiten goldbraun braten.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-03.webp","image_alt":"Farofa mit Kochbanane und geröstetem Maniokmehl: Kochbanane bräunen"},{"title":"Herausnehmen","content":"Kochbanane unzerdrückt auf einen Teller geben. Die gebräunte Butter in der Pfanne lassen, sofern sie nicht verbrannt ist.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-04.webp","image_alt":"Farofa mit Kochbanane und geröstetem Maniokmehl: Herausnehmen"},{"title":"Zwiebel dünsten","content":"Übrige 15 g Butter und Zwiebel in die Pfanne geben. Unter Rühren 5–6 Minuten weich und leicht goldgelb dünsten.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-05.webp","image_alt":"Farofa mit Kochbanane und geröstetem Maniokmehl: Zwiebel dünsten"},{"title":"Maniokmehl rösten","content":"Geröstetes Maniokmehl zugeben und bei mittlerer bis kleiner Hitze 3–4 Minuten rühren. Es soll duften und locker bleiben, nicht zu einer Paste werden.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-06.webp","image_alt":"Farofa mit Kochbanane und geröstetem Maniokmehl: Maniokmehl rösten"},{"title":"Vorsichtig mischen","content":"Kochbanane zurückgeben, Schnittlauch, Salz und Pfeffer zugeben und 1 Minute vorsichtig unterheben. Frucht nicht zerdrücken und kein Wasser zufügen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-07.webp","image_alt":"Farofa mit Kochbanane und geröstetem Maniokmehl: Vorsichtig mischen"},{"title":"Servieren","content":"In eine Schüssel füllen und auf sechs Beilagenportionen verteilen. Warm zu Bohnen oder einem Hauptgericht servieren; Beilagen sind nicht in den Nährwerten enthalten.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-08.webp","image_alt":"Farofa mit Kochbanane und geröstetem Maniokmehl: Servieren"}],"category":"Beilagen","course":"Beilagen","cuisine":"Brasilianisch","difficulty":"Einfach","prep_time_minutes":10,"cook_time_minutes":20,"total_time_minutes":30,"servings":6,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada.webp","alt":"Farofa mit Kochbanane und geröstetem Maniokmehl"}],"video_urls":[],"keywords":["Farofa mit Kochbanane und geröstetem Maniokmehl","Reife Kochbanane, geschält","Grobes geröstetes Maniokmehl"],"nutrition":{"calories":216,"protein_g":1.3,"carbs_g":44.4,"fat_g":5.0,"saturated_fat_g":3.0,"fiber_g":3.2,"sodium_mg":136.0,"estimated":true,"serving_size":"1 von 6 Portionen","source":"USDA FoodData Central SR Legacy + TBCA BRC0088B","source_url":"https://www.tbca.net.br/base-dados-en/int_statistical_composition.php?cod_produto=BRC0088B","method":"Referenzwerte nach Zutatengewicht summiert und durch die Portionen geteilt.","note":"Ungefähre Schätzung, keine Messung des fertigen Gerichts. Marken und Abtropfen verändern die Werte; unvollständige Nährstoffdaten werden nicht angezeigt. Generische Referenzen für Senf, Sahne, Süßkartoffeln, Öl und Schokolade; Sorten und Marken können abweichen."},"seo":{"title":"Farofa mit Kochbanane und geröstetem Maniokmehl","description":"Brasilianische Farofa mit reifer Kochbanane, Butter und grobem geröstetem Maniokmehl. Eine lockere, goldene Beilage für sechs in etwa 30 Minuten.","image_alt":"Farofa mit Kochbanane und geröstetem Maniokmehl","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada-16x9.webp"],"faq":[{"q":"Ist Maniokmehl dasselbe wie Tapiokastärke?","a":"Nein. Farofa benötigt körniges, geröstetes Maniokmehl. Feine Tapiokastärke ergibt eine andere Konsistenz und ist kein direkter Ersatz."},{"q":"Kann ich eine normale Banane verwenden?","a":"Sie ist weicher und süßer und zerfällt leichter. Mengen und Nährwerte dieses Rezepts basieren auf reifer Kochbanane."},{"q":"Warum ist die Farofa feucht?","a":"Sehr weiche Früchte oder zusätzliche Flüssigkeit lassen sie klumpen. Feste Kochbanane separat bräunen und kein Wasser zugeben."}],"rest_time_minutes":0},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"89f06449-417d-48df-bcfe-628c059eb3ca"},{"language":"en","slug":"plantain-farofa-toasted-cassava","public_path":"/en/plantain-farofa-toasted-cassava","title":"Plantain farofa with toasted cassava flour","excerpt":"Brazilian farofa with ripe cooking plantain, butter and toasted cassava meal. A loose, golden side dish for six, ready in about 30 minutes.","summary":"Brazilian farofa with ripe cooking plantain, butter and toasted cassava meal. A loose, golden side dish for six, ready in about 30 minutes.","notes":"<p>Use coarse toasted cassava meal (farinha de mandioca torrada), not tapioca starch, and cooking plantain rather than a soft dessert banana. Contains milk from butter. Refrigerate leftovers within 2 hours and use within 2 days; reheat in a dry pan. Cassava-flour nutrition uses the Brazilian TBCA reference; total sugars are omitted because that reference does not provide a complete value.</p><h2>You may also like</h2><ul><li><a href=\"/en/feijoada-recipe\">Home-style black bean and pork feijoada</a></li><li><a href=\"/en/perfect-white-rice\">Fluffy white rice by the absorption method</a></li></ul>","content_html":"<p>Brazilian farofa with ripe cooking plantain, butter and toasted cassava meal. A loose, golden side dish for six, ready in about 30 minutes.</p><p>Use coarse toasted cassava meal (farinha de mandioca torrada), not tapioca starch, and cooking plantain rather than a soft dessert banana. Contains milk from butter. Refrigerate leftovers within 2 hours and use within 2 days; reheat in a dry pan. Cassava-flour nutrition uses the Brazilian TBCA reference; total sugars are omitted because that reference does not provide a complete value.</p><h2>You may also like</h2><ul><li><a href=\"/en/feijoada-recipe\">Home-style black bean and pork feijoada</a></li><li><a href=\"/en/perfect-white-rice\">Fluffy white rice by the absorption method</a></li></ul>","ingredients":[{"name":"Ripe cooking plantain, peeled","amount":"300","unit":"g"},{"name":"Coarse toasted cassava meal","amount":"180","unit":"g"},{"name":"Unsalted butter","amount":"35","unit":"g"},{"name":"Peeled onion","amount":"100","unit":"g"},{"name":"Fresh chives","amount":"10","unit":"g"},{"name":"Salt","amount":"2","unit":"g"},{"name":"Ground black pepper","amount":"0.5","unit":"g"}],"steps":[{"title":"Cut the plantain","content":"Peel the ripe cooking plantain and weigh 300 g flesh. Cut into 1.5 cm cubes; choose ripe but firm fruit that will hold its shape.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-01.webp","image_alt":"Plantain farofa with toasted cassava flour: Cut the plantain"},{"title":"Prepare the aromatics","content":"Finely chop the onion and chives. Weigh 180 g toasted cassava meal and divide the butter into 20 g and 15 g portions.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-02.webp","image_alt":"Plantain farofa with toasted cassava flour: Prepare the aromatics"},{"title":"Brown the plantain","content":"Melt 20 g butter in a wide pan over medium heat. Cook the plantain for 5–7 minutes, turning carefully, until golden on several sides.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-03.webp","image_alt":"Plantain farofa with toasted cassava flour: Brown the plantain"},{"title":"Set aside","content":"Transfer the plantain to a plate without crushing it. Leave the browned butter in the pan, provided it has not burned.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-04.webp","image_alt":"Plantain farofa with toasted cassava flour: Set aside"},{"title":"Soften the onion","content":"Add the remaining 15 g butter and the onion. Cook for 5–6 minutes, stirring, until softened and lightly golden.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-05.webp","image_alt":"Plantain farofa with toasted cassava flour: Soften the onion"},{"title":"Toast the meal","content":"Add the toasted cassava meal and stir over medium-low heat for 3–4 minutes. It should smell toasted and stay loose, without becoming a paste.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-06.webp","image_alt":"Plantain farofa with toasted cassava flour: Toast the meal"},{"title":"Combine gently","content":"Return the plantain, add chives, salt and pepper, and fold gently for 1 minute. Avoid crushing the fruit and do not add water.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-07.webp","image_alt":"Plantain farofa with toasted cassava flour: Combine gently"},{"title":"Serve","content":"Transfer to a serving dish and divide into six side portions. Serve warm alongside beans or a main dish; accompaniments are not included in the nutrition.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-08.webp","image_alt":"Plantain farofa with toasted cassava flour: Serve"}],"category":"Side dishes","course":"Side dishes","cuisine":"Brazilian","difficulty":"Easy","prep_time_minutes":10,"cook_time_minutes":20,"total_time_minutes":30,"servings":6,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada.webp","alt":"Plantain farofa with toasted cassava flour"}],"video_urls":[],"keywords":["Plantain farofa with toasted cassava flour","Ripe cooking plantain, peeled","Coarse toasted cassava meal"],"nutrition":{"calories":216,"protein_g":1.3,"carbs_g":44.4,"fat_g":5.0,"saturated_fat_g":3.0,"fiber_g":3.2,"sodium_mg":136.0,"estimated":true,"serving_size":"1 of 6 servings","source":"USDA FoodData Central SR Legacy + TBCA BRC0088B","source_url":"https://www.tbca.net.br/base-dados-en/int_statistical_composition.php?cod_produto=BRC0088B","method":"Reference nutrients summed by ingredient weight and divided by servings.","note":"Approximate estimate, not a measurement of the cooked dish. Brands and draining change values; nutrients with incomplete data are omitted. Generic references for prepared mustard, cream, sweet potato, oil and chocolate; specific varieties and brands can differ."},"seo":{"title":"Plantain farofa with toasted cassava flour","description":"Brazilian farofa with ripe cooking plantain, butter and toasted cassava meal. A loose, golden side dish for six, ready in about 30 minutes.","image_alt":"Plantain farofa with toasted cassava flour","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada-16x9.webp"],"faq":[{"q":"Is cassava meal the same as tapioca starch?","a":"No. Farofa needs toasted, granular cassava meal. Fine tapioca starch makes a different texture and is not a direct substitute."},{"q":"Can I use a dessert banana?","a":"It is softer and sweeter and breaks more easily. This recipe and its nutrition use ripe cooking plantain."},{"q":"Why is my farofa wet?","a":"Very soft fruit or added liquid can make it clump. Keep the plantain firm, brown it separately and add no water."}],"rest_time_minutes":0},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"89f06449-417d-48df-bcfe-628c059eb3ca"},{"language":"fr","slug":"farofa-banane-plantain-manioc","public_path":"/fr/farofa-banane-plantain-manioc","title":"Farofa à la banane plantain et au manioc torréfié","excerpt":"Une farofa brésilienne avec banane plantain mûre, beurre et farine de manioc torréfiée. Un accompagnement doré et granuleux pour six, prêt en 30 minutes.","summary":"Une farofa brésilienne avec banane plantain mûre, beurre et farine de manioc torréfiée. Un accompagnement doré et granuleux pour six, prêt en 30 minutes.","notes":"<p>Utilisez de la farine de manioc torréfiée granuleuse (farinha de mandioca torrada), pas de fécule de tapioca, et une banane plantain plutôt qu’une banane dessert molle. Contient du lait via le beurre. Réfrigérez avant 2 heures et consommez sous 2 jours ; réchauffez à la poêle sèche. La référence de manioc vient de la TBCA brésilienne ; les sucres totaux sont omis faute de données complètes.</p><h2>À préparer aussi</h2><ul><li><a href=\"/fr/recette-de-feijoada\">Feijoada maison aux haricots noirs et au porc</a></li><li><a href=\"/fr/riz-blanc-parfait\">Riz blanc aux grains séparés par absorption</a></li></ul>","content_html":"<p>Une farofa brésilienne avec banane plantain mûre, beurre et farine de manioc torréfiée. Un accompagnement doré et granuleux pour six, prêt en 30 minutes.</p><p>Utilisez de la farine de manioc torréfiée granuleuse (farinha de mandioca torrada), pas de fécule de tapioca, et une banane plantain plutôt qu’une banane dessert molle. Contient du lait via le beurre. Réfrigérez avant 2 heures et consommez sous 2 jours ; réchauffez à la poêle sèche. La référence de manioc vient de la TBCA brésilienne ; les sucres totaux sont omis faute de données complètes.</p><h2>À préparer aussi</h2><ul><li><a href=\"/fr/recette-de-feijoada\">Feijoada maison aux haricots noirs et au porc</a></li><li><a href=\"/fr/riz-blanc-parfait\">Riz blanc aux grains séparés par absorption</a></li></ul>","ingredients":[{"name":"Banane plantain mûre, épluchée","amount":"300","unit":"g"},{"name":"Farine de manioc torréfiée grossière","amount":"180","unit":"g"},{"name":"Beurre doux","amount":"35","unit":"g"},{"name":"Oignon épluché","amount":"100","unit":"g"},{"name":"Ciboulette fraîche","amount":"10","unit":"g"},{"name":"Sel","amount":"2","unit":"g"},{"name":"Poivre noir moulu","amount":"0.5","unit":"g"}],"steps":[{"title":"Découper la plantain","content":"Épluchez la banane plantain mûre et pesez 300 g de chair. Coupez en dés de 1,5 cm ; choisissez un fruit mûr mais ferme.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-01.webp","image_alt":"Farofa à la banane plantain et au manioc torréfié: Découper la plantain"},{"title":"Préparer les aromates","content":"Hachez finement oignon et ciboulette. Pesez 180 g de farine de manioc torréfiée et séparez le beurre en portions de 20 g et 15 g.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-02.webp","image_alt":"Farofa à la banane plantain et au manioc torréfié: Préparer les aromates"},{"title":"Dorer la plantain","content":"Faites fondre 20 g de beurre dans une grande poêle à feu moyen. Dorez la plantain 5–7 minutes en la retournant délicatement sur plusieurs faces.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-03.webp","image_alt":"Farofa à la banane plantain et au manioc torréfié: Dorer la plantain"},{"title":"Réserver","content":"Transférez les dés sur une assiette sans les écraser. Gardez le beurre doré dans la poêle à condition qu’il ne soit pas brûlé.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-04.webp","image_alt":"Farofa à la banane plantain et au manioc torréfié: Réserver"},{"title":"Cuire l’oignon","content":"Ajoutez les 15 g de beurre restants et l’oignon. Faites revenir 5–6 minutes en remuant, jusqu’à tendreté et légère coloration.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-05.webp","image_alt":"Farofa à la banane plantain et au manioc torréfié: Cuire l’oignon"},{"title":"Torréfier la farine","content":"Ajoutez la farine de manioc torréfiée et remuez à feu moyen-doux pendant 3–4 minutes. Elle doit sentir le grillé et rester granuleuse, sans former une pâte.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-06.webp","image_alt":"Farofa à la banane plantain et au manioc torréfié: Torréfier la farine"},{"title":"Mélanger doucement","content":"Remettez la plantain, ajoutez ciboulette, sel et poivre. Mélangez délicatement 1 minute sans écraser les dés et sans ajouter d’eau.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-07.webp","image_alt":"Farofa à la banane plantain et au manioc torréfié: Mélanger doucement"},{"title":"Servir","content":"Transférez dans un plat et répartissez en six portions d’accompagnement. Servez chaud avec des haricots ou un plat principal, non compris dans la nutrition.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-08.webp","image_alt":"Farofa à la banane plantain et au manioc torréfié: Servir"}],"category":"Accompagnements","course":"Accompagnements","cuisine":"Brésilienne","difficulty":"Facile","prep_time_minutes":10,"cook_time_minutes":20,"total_time_minutes":30,"servings":6,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada.webp","alt":"Farofa à la banane plantain et au manioc torréfié"}],"video_urls":[],"keywords":["Farofa à la banane plantain et au manioc torréfié","Banane plantain mûre, épluchée","Farine de manioc torréfiée grossière"],"nutrition":{"calories":216,"protein_g":1.3,"carbs_g":44.4,"fat_g":5.0,"saturated_fat_g":3.0,"fiber_g":3.2,"sodium_mg":136.0,"estimated":true,"serving_size":"1 des 6 portions","source":"USDA FoodData Central SR Legacy + TBCA BRC0088B","source_url":"https://www.tbca.net.br/base-dados-en/int_statistical_composition.php?cod_produto=BRC0088B","method":"Somme des références selon le poids des ingrédients, divisée par le nombre de portions.","note":"Estimation indicative, pas une mesure du plat cuisiné. Marques et égouttage changent les valeurs ; les nutriments incomplets ne sont pas affichés. Références génériques pour moutarde préparée, crème, patate douce, huile et chocolat ; variétés et marques peuvent différer."},"seo":{"title":"Farofa à la banane plantain et au manioc torréfié","description":"Une farofa brésilienne avec banane plantain mûre, beurre et farine de manioc torréfiée. Un accompagnement doré et granuleux pour six, prêt en 30 minutes.","image_alt":"Farofa à la banane plantain et au manioc torréfié","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada-16x9.webp"],"faq":[{"q":"Farine de manioc et tapioca sont-ils identiques ?","a":"Non. La farofa demande une farine de manioc torréfiée et granuleuse. La fécule fine de tapioca donne une autre texture et ne convient pas en remplacement direct."},{"q":"Puis-je utiliser une banane dessert ?","a":"Elle est plus molle et sucrée et s’écrase plus facilement. Cette recette et sa nutrition utilisent une banane plantain mûre."},{"q":"Pourquoi ma farofa est-elle humide ?","a":"Un fruit trop mou ou du liquide ajouté la fait s’agglomérer. Dorez séparément une plantain ferme et n’ajoutez pas d’eau."}],"rest_time_minutes":0},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"89f06449-417d-48df-bcfe-628c059eb3ca"},{"language":"it","slug":"farofa-platano-farina-manioca","public_path":"/it/farofa-platano-farina-manioca","title":"Farofa di platano con farina di manioca tostata","excerpt":"Farofa brasiliana con platano maturo, burro e farina di manioca tostata. Un contorno dorato e sgranato per sei, pronto in circa 30 minuti.","summary":"Farofa brasiliana con platano maturo, burro e farina di manioca tostata. Un contorno dorato e sgranato per sei, pronto in circa 30 minuti.","notes":"<p>Usa farina di manioca tostata e granulosa (farinha de mandioca torrada), non amido di tapioca, e platano da cottura anziché banana dolce morbida. Contiene latte dal burro. Conserva in frigorifero entro 2 ore e consuma entro 2 giorni; riscalda in padella asciutta. Il riferimento della manioca è la TBCA brasiliana; gli zuccheri totali sono omessi perché il dato è incompleto.</p><h2>Da provare anche</h2><ul><li><a href=\"/it/feijoada-ricetta\">Feijoada casalinga con fagioli neri e maiale</a></li><li><a href=\"/it/riso-bianco-perfetto\">Riso bianco sgranato con cottura per assorbimento</a></li></ul>","content_html":"<p>Farofa brasiliana con platano maturo, burro e farina di manioca tostata. Un contorno dorato e sgranato per sei, pronto in circa 30 minuti.</p><p>Usa farina di manioca tostata e granulosa (farinha de mandioca torrada), non amido di tapioca, e platano da cottura anziché banana dolce morbida. Contiene latte dal burro. Conserva in frigorifero entro 2 ore e consuma entro 2 giorni; riscalda in padella asciutta. Il riferimento della manioca è la TBCA brasiliana; gli zuccheri totali sono omessi perché il dato è incompleto.</p><h2>Da provare anche</h2><ul><li><a href=\"/it/feijoada-ricetta\">Feijoada casalinga con fagioli neri e maiale</a></li><li><a href=\"/it/riso-bianco-perfetto\">Riso bianco sgranato con cottura per assorbimento</a></li></ul>","ingredients":[{"name":"Platano maturo, sbucciato","amount":"300","unit":"g"},{"name":"Farina di manioca tostata a grana grossa","amount":"180","unit":"g"},{"name":"Burro non salato","amount":"35","unit":"g"},{"name":"Cipolla sbucciata","amount":"100","unit":"g"},{"name":"Erba cipollina fresca","amount":"10","unit":"g"},{"name":"Sale","amount":"2","unit":"g"},{"name":"Pepe nero macinato","amount":"0.5","unit":"g"}],"steps":[{"title":"Taglia il platano","content":"Sbuccia il platano maturo e pesa 300 g di polpa. Taglia a cubetti di 1,5 cm; scegli frutti maturi ma sodi, che mantengano la forma.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-01.webp","image_alt":"Farofa di platano con farina di manioca tostata: Taglia il platano"},{"title":"Prepara gli aromi","content":"Trita finemente cipolla ed erba cipollina. Pesa 180 g di farina di manioca tostata e dividi il burro in 20 g e 15 g.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-02.webp","image_alt":"Farofa di platano con farina di manioca tostata: Prepara gli aromi"},{"title":"Dora il platano","content":"Sciogli 20 g di burro in una padella ampia a fuoco medio. Cuoci il platano per 5–7 minuti girandolo con cautela, fino a dorare più lati.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-03.webp","image_alt":"Farofa di platano con farina di manioca tostata: Dora il platano"},{"title":"Metti da parte","content":"Trasferisci su un piatto senza schiacciare i cubetti. Lascia il burro dorato in padella, purché non sia bruciato.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-04.webp","image_alt":"Farofa di platano con farina di manioca tostata: Metti da parte"},{"title":"Cuoci la cipolla","content":"Aggiungi i 15 g di burro rimasti e la cipolla. Cuoci per 5–6 minuti mescolando, finché è morbida e leggermente dorata.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-05.webp","image_alt":"Farofa di platano con farina di manioca tostata: Cuoci la cipolla"},{"title":"Tosta la farina","content":"Unisci la farina di manioca tostata e mescola a fuoco medio-basso per 3–4 minuti. Deve profumare di tostato e restare sgranata, senza diventare una pasta.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-06.webp","image_alt":"Farofa di platano con farina di manioca tostata: Tosta la farina"},{"title":"Mescola delicatamente","content":"Rimetti il platano, aggiungi erba cipollina, sale e pepe. Mescola delicatamente per 1 minuto, senza schiacciare la frutta né aggiungere acqua.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-07.webp","image_alt":"Farofa di platano con farina di manioca tostata: Mescola delicatamente"},{"title":"Servi","content":"Trasferisci in una ciotola e dividi in sei porzioni da contorno. Servi caldo con fagioli o un piatto principale, non inclusi nella nutrizione.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-08.webp","image_alt":"Farofa di platano con farina di manioca tostata: Servi"}],"category":"Contorni","course":"Contorni","cuisine":"Brasiliana","difficulty":"Facile","prep_time_minutes":10,"cook_time_minutes":20,"total_time_minutes":30,"servings":6,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada.webp","alt":"Farofa di platano con farina di manioca tostata"}],"video_urls":[],"keywords":["Farofa di platano con farina di manioca tostata","Platano maturo, sbucciato","Farina di manioca tostata a grana grossa"],"nutrition":{"calories":216,"protein_g":1.3,"carbs_g":44.4,"fat_g":5.0,"saturated_fat_g":3.0,"fiber_g":3.2,"sodium_mg":136.0,"estimated":true,"serving_size":"1 di 6 porzioni","source":"USDA FoodData Central SR Legacy + TBCA BRC0088B","source_url":"https://www.tbca.net.br/base-dados-en/int_statistical_composition.php?cod_produto=BRC0088B","method":"Somma dei valori di riferimento per peso, divisa per le porzioni.","note":"Stima indicativa, non misurazione del piatto cotto. Marche e scolatura modificano i valori; nutrienti con dati incompleti non sono mostrati. Riferimenti generici per senape preparata, panna, patata dolce, olio e cioccolato; varietà e marche possono differire."},"seo":{"title":"Farofa di platano con farina di manioca tostata","description":"Farofa brasiliana con platano maturo, burro e farina di manioca tostata. Un contorno dorato e sgranato per sei, pronto in circa 30 minuti.","image_alt":"Farofa di platano con farina di manioca tostata","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada-16x9.webp"],"faq":[{"q":"Farina di manioca e tapioca sono uguali?","a":"No. La farofa richiede farina di manioca tostata granulosa. L’amido fine di tapioca dà una consistenza diversa e non è un sostituto diretto."},{"q":"Posso usare una banana comune?","a":"È più morbida e dolce e si rompe facilmente. Questa ricetta e la nutrizione usano platano maturo."},{"q":"Perché la farofa è umida?","a":"Frutta troppo morbida o liquido aggiunto fanno formare grumi. Dora separatamente il platano sodo e non aggiungere acqua."}],"rest_time_minutes":0},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"89f06449-417d-48df-bcfe-628c059eb3ca"},{"language":"ja","slug":"plantain-cassava-farofa","public_path":"/ja/plantain-cassava-farofa","title":"プランテンのファロファ：炒りキャッサバ粉のブラジル風付け合わせ","excerpt":"熟した調理用バナナ、バター、炒りキャッサバ粉を合わせるブラジルのファロファ。ぽろぽろした黄金色の付け合わせ6人分を約30分で作ります。","summary":"熟した調理用バナナ、バター、炒りキャッサバ粉を合わせるブラジルのファロファ。ぽろぽろした黄金色の付け合わせ6人分を約30分で作ります。","notes":"<p>粒状の炒りキャッサバ粉（farinha de mandioca torrada）を使い、タピオカでんぷんには替えません。柔らかい生食用バナナではなくプランテンを使います。バター由来の乳を含みます。2時間以内に冷蔵し、2日以内に食べ、油を加えないフライパンで温めます。粉の栄養値はブラジルTBCAを使用し、完全な値がない総糖類は表示していません。</p><h2>こちらのレシピも</h2><ul><li><a href=\"/ja/フェイジョアーダのレシピ\">黒豆と豚肉の家庭風フェイジョアーダ</a></li><li><a href=\"/ja/完璧な白米\">吸水法で炊く、粒がほぐれる白米</a></li></ul>","content_html":"<p>熟した調理用バナナ、バター、炒りキャッサバ粉を合わせるブラジルのファロファ。ぽろぽろした黄金色の付け合わせ6人分を約30分で作ります。</p><p>粒状の炒りキャッサバ粉（farinha de mandioca torrada）を使い、タピオカでんぷんには替えません。柔らかい生食用バナナではなくプランテンを使います。バター由来の乳を含みます。2時間以内に冷蔵し、2日以内に食べ、油を加えないフライパンで温めます。粉の栄養値はブラジルTBCAを使用し、完全な値がない総糖類は表示していません。</p><h2>こちらのレシピも</h2><ul><li><a href=\"/ja/フェイジョアーダのレシピ\">黒豆と豚肉の家庭風フェイジョアーダ</a></li><li><a href=\"/ja/完璧な白米\">吸水法で炊く、粒がほぐれる白米</a></li></ul>","ingredients":[{"name":"熟したプランテン（調理用バナナ、皮を除く）","amount":"300","unit":"g"},{"name":"粗挽きの炒りキャッサバ粉","amount":"180","unit":"g"},{"name":"無塩バター","amount":"35","unit":"g"},{"name":"玉ねぎ（皮を除く）","amount":"100","unit":"g"},{"name":"チャイブ","amount":"10","unit":"g"},{"name":"塩","amount":"2","unit":"g"},{"name":"黒こしょう（粉）","amount":"0.5","unit":"g"}],"steps":[{"title":"プランテンを切る","content":"熟したプランテンの皮をむき、果肉300 gを量ります。1.5 cm角に切ります。熟していても形を保つ硬さのものを選びます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-01.webp","image_alt":"プランテンのファロファ：炒りキャッサバ粉のブラジル風付け合わせ: プランテンを切る"},{"title":"香味野菜を準備","content":"玉ねぎとチャイブを細かく切ります。炒りキャッサバ粉180 gを量り、バターを20 gと15 gに分けます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-02.webp","image_alt":"プランテンのファロファ：炒りキャッサバ粉のブラジル風付け合わせ: 香味野菜を準備"},{"title":"プランテンを焼く","content":"大きなフライパンでバター20 gを中火で溶かします。プランテンを5〜7分、慎重に返して数面に焼き色を付けます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-03.webp","image_alt":"プランテンのファロファ：炒りキャッサバ粉のブラジル風付け合わせ: プランテンを焼く"},{"title":"取り出す","content":"角切りをつぶさず皿に取り出します。バターが焦げていなければ、そのままフライパンに残します。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-04.webp","image_alt":"プランテンのファロファ：炒りキャッサバ粉のブラジル風付け合わせ: 取り出す"},{"title":"玉ねぎを炒める","content":"残りのバター15 gと玉ねぎを加え、5〜6分混ぜながら柔らかく薄いきつね色になるまで炒めます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-05.webp","image_alt":"プランテンのファロファ：炒りキャッサバ粉のブラジル風付け合わせ: 玉ねぎを炒める"},{"title":"粉を炒る","content":"炒りキャッサバ粉を加え、中弱火で3〜4分混ぜます。香ばしく、ぽろぽろした状態を保ち、ペーストにしません。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-06.webp","image_alt":"プランテンのファロファ：炒りキャッサバ粉のブラジル風付け合わせ: 粉を炒る"},{"title":"優しく合わせる","content":"プランテンを戻し、チャイブ、塩、こしょうを加えて1分優しく混ぜます。実をつぶさず、水も加えません。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-07.webp","image_alt":"プランテンのファロファ：炒りキャッサバ粉のブラジル風付け合わせ: 優しく合わせる"},{"title":"盛り付ける","content":"器に移して付け合わせ6人分に分けます。温かくして豆料理や主菜に添えます。添える料理の栄養値は含みません。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-08.webp","image_alt":"プランテンのファロファ：炒りキャッサバ粉のブラジル風付け合わせ: 盛り付ける"}],"category":"付け合わせ","course":"付け合わせ","cuisine":"ブラジル料理","difficulty":"簡単","prep_time_minutes":10,"cook_time_minutes":20,"total_time_minutes":30,"servings":6,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada.webp","alt":"プランテンのファロファ：炒りキャッサバ粉のブラジル風付け合わせ"}],"video_urls":[],"keywords":["プランテンのファロファ：炒りキャッサバ粉のブラジル風付け合わせ","熟したプランテン（調理用バナナ、皮を除く）","粗挽きの炒りキャッサバ粉"],"nutrition":{"calories":216,"protein_g":1.3,"carbs_g":44.4,"fat_g":5.0,"saturated_fat_g":3.0,"fiber_g":3.2,"sodium_mg":136.0,"estimated":true,"serving_size":"全6人分のうち1人分","source":"USDA FoodData Central SR Legacy + TBCA BRC0088B","source_url":"https://www.tbca.net.br/base-dados-en/int_statistical_composition.php?cod_produto=BRC0088B","method":"材料の重量に応じた参考栄養値を合計し、人数で割っています。","note":"調理済み料理の実測値ではなく概算です。商品や水切りで変わり、資料がそろわない栄養素は表示しません。 マスタード、生クリーム、さつまいも、油、チョコレートは一般的な参考値を使用し、品種や商品で異なります。"},"seo":{"title":"プランテンのファロファ：炒りキャッサバ粉のブラジル風付け合わせ","description":"熟した調理用バナナ、バター、炒りキャッサバ粉を合わせるブラジルのファロファ。ぽろぽろした黄金色の付け合わせ6人分を約30分で作ります。","image_alt":"プランテンのファロファ：炒りキャッサバ粉のブラジル風付け合わせ","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada-16x9.webp"],"faq":[{"q":"キャッサバ粉とタピオカでんぷんは同じ？","a":"違います。ファロファには粒のある炒りキャッサバ粉が必要です。細かいタピオカでんぷんでは食感が変わり、そのまま代用できません。"},{"q":"普通のバナナでも作れますか？","a":"より柔らかく甘いため崩れやすくなります。このレシピと栄養値は熟したプランテンを基準にしています。"},{"q":"ファロファが湿る原因は？","a":"柔らかすぎる実や追加の水分で粉が固まります。硬さのあるプランテンを別に焼き、水を加えないでください。"}],"rest_time_minutes":0},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"89f06449-417d-48df-bcfe-628c059eb3ca"},{"language":"pt","slug":"farofa-banana-da-terra-manteiga","public_path":"/pt/farofa-banana-da-terra-manteiga","title":"Farofa de banana-da-terra com farinha de mandioca torrada","excerpt":"Farofa de banana-da-terra madura com manteiga, cebola e farinha de mandioca torrada. Um acompanhamento soltinho e dourado para seis, pronto em cerca de 30 minutos.","summary":"Farofa de banana-da-terra madura com manteiga, cebola e farinha de mandioca torrada. Um acompanhamento soltinho e dourado para seis, pronto em cerca de 30 minutos.","notes":"<p>Use farinha de mandioca torrada e granulada, não fécula de tapioca, e banana-da-terra em vez de banana de sobremesa muito macia. Contém leite por causa da manteiga. Refrigere antes de 2 horas e consuma em até 2 dias; reaqueça em frigideira seca. A referência nutricional da farinha é da TBCA; açúcares totais foram omitidos por falta de dados completos.</p><h2>Prepare também</h2><ul><li><a href=\"/pt/feijoada\">Feijoada caseira de feijão preto e porco</a></li><li><a href=\"/pt/arroz-branco-soltinho\">Arroz branco soltinho pelo método de absorção</a></li></ul>","content_html":"<p>Farofa de banana-da-terra madura com manteiga, cebola e farinha de mandioca torrada. Um acompanhamento soltinho e dourado para seis, pronto em cerca de 30 minutos.</p><p>Use farinha de mandioca torrada e granulada, não fécula de tapioca, e banana-da-terra em vez de banana de sobremesa muito macia. Contém leite por causa da manteiga. Refrigere antes de 2 horas e consuma em até 2 dias; reaqueça em frigideira seca. A referência nutricional da farinha é da TBCA; açúcares totais foram omitidos por falta de dados completos.</p><h2>Prepare também</h2><ul><li><a href=\"/pt/feijoada\">Feijoada caseira de feijão preto e porco</a></li><li><a href=\"/pt/arroz-branco-soltinho\">Arroz branco soltinho pelo método de absorção</a></li></ul>","ingredients":[{"name":"Banana-da-terra madura, descascada","amount":"300","unit":"g"},{"name":"Farinha de mandioca torrada grossa","amount":"180","unit":"g"},{"name":"Manteiga sem sal","amount":"35","unit":"g"},{"name":"Cebola descascada","amount":"100","unit":"g"},{"name":"Cebolinha fresca","amount":"10","unit":"g"},{"name":"Sal","amount":"2","unit":"g"},{"name":"Pimenta-do-reino moída","amount":"0.5","unit":"g"}],"steps":[{"title":"Corte a banana","content":"Descasque a banana-da-terra e pese 300 g de polpa. Corte em cubos de 1,5 cm; escolha fruta madura, mas firme, para manter o formato.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-01.webp","image_alt":"Farofa de banana-da-terra com farinha de mandioca torrada: Corte a banana"},{"title":"Prepare os temperos","content":"Pique cebola e cebolinha finamente. Pese 180 g de farinha de mandioca torrada e divida a manteiga em porções de 20 g e 15 g.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-02.webp","image_alt":"Farofa de banana-da-terra com farinha de mandioca torrada: Prepare os temperos"},{"title":"Doure a banana","content":"Derreta 20 g de manteiga numa frigideira grande em fogo médio. Doure a banana por 5–7 minutos, virando com cuidado para colorir vários lados.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-03.webp","image_alt":"Farofa de banana-da-terra com farinha de mandioca torrada: Doure a banana"},{"title":"Reserve","content":"Transfira os cubos para um prato sem amassar. Deixe a manteiga dourada na frigideira, desde que não tenha queimado.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-04.webp","image_alt":"Farofa de banana-da-terra com farinha de mandioca torrada: Reserve"},{"title":"Refogue a cebola","content":"Junte os 15 g de manteiga restantes e a cebola. Refogue por 5–6 minutos, mexendo, até amaciar e dourar levemente.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-05.webp","image_alt":"Farofa de banana-da-terra com farinha de mandioca torrada: Refogue a cebola"},{"title":"Toste a farinha","content":"Acrescente a farinha de mandioca torrada e mexa em fogo médio-baixo por 3–4 minutos. Ela deve ficar cheirosa e solta, sem virar uma pasta.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-06.webp","image_alt":"Farofa de banana-da-terra com farinha de mandioca torrada: Toste a farinha"},{"title":"Misture delicadamente","content":"Volte a banana, acrescente cebolinha, sal e pimenta e envolva por 1 minuto. Não amasse os cubos nem adicione água.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-07.webp","image_alt":"Farofa de banana-da-terra com farinha de mandioca torrada: Misture delicadamente"},{"title":"Sirva","content":"Passe para uma travessa e divida em seis porções de acompanhamento. Sirva morno com feijão ou prato principal; os acompanhamentos não estão incluídos na nutrição.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/paso-08.webp","image_alt":"Farofa de banana-da-terra com farinha de mandioca torrada: Sirva"}],"category":"Acompanhamentos","course":"Acompanhamentos","cuisine":"Brasileira","difficulty":"Fácil","prep_time_minutes":10,"cook_time_minutes":20,"total_time_minutes":30,"servings":6,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada.webp","alt":"Farofa de banana-da-terra com farinha de mandioca torrada"}],"video_urls":[],"keywords":["Farofa de banana-da-terra com farinha de mandioca torrada","Banana-da-terra madura, descascada","Farinha de mandioca torrada grossa"],"nutrition":{"calories":216,"protein_g":1.3,"carbs_g":44.4,"fat_g":5.0,"saturated_fat_g":3.0,"fiber_g":3.2,"sodium_mg":136.0,"estimated":true,"serving_size":"1 das 6 porções","source":"USDA FoodData Central SR Legacy + TBCA BRC0088B","source_url":"https://www.tbca.net.br/base-dados-en/int_statistical_composition.php?cod_produto=BRC0088B","method":"Soma das referências pelo peso dos ingredientes, dividida pelas porções.","note":"Estimativa orientativa, não medição do prato pronto. Marcas e escorrimento alteram os valores; nutrientes com dados incompletos não são mostrados. Referências genéricas para mostarda preparada, creme, batata-doce, óleo e chocolate; variedades e marcas podem diferir."},"seo":{"title":"Farofa de banana-da-terra com farinha de mandioca torrada","description":"Farofa de banana-da-terra madura com manteiga, cebola e farinha de mandioca torrada. Um acompanhamento soltinho e dourado para seis, pronto em cerca de 30 minutos.","image_alt":"Farofa de banana-da-terra com farinha de mandioca torrada","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/farofa-platano-maduro/portada-16x9.webp"],"faq":[{"q":"Farinha de mandioca e tapioca são a mesma coisa?","a":"Não. A farofa precisa da farinha torrada e granulada. Fécula de tapioca fina produz outra textura e não é substituição direta."},{"q":"Posso usar banana-prata?","a":"Ela é mais macia e doce e pode se desfazer. Esta receita e a nutrição foram calculadas com banana-da-terra madura."},{"q":"Por que a farofa ficou úmida?","a":"Fruta muito mole ou líquido extra fazem a farinha empelotar. Doure a banana firme separadamente e não acrescente água."}],"rest_time_minutes":0},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"89f06449-417d-48df-bcfe-628c059eb3ca"}]$expected$::jsonb; x jsonb; v public.recipes; n int:=0;
BEGIN
